from collections import defaultdict
from typing import List

class Solution:
    def wordSquares(self, words: List[str]) -> List[List[str]]:
        n = len(words[0])
        prefix_map = defaultdict(list)
        for w in words:
            for i in range(n + 1):
                prefix_map[w[:i]].append(w)

        res = []
        curr = []

        def backtrack(step: int):
            if step == n:
                res.append(list(curr))
                return
            prefix = "".join(curr[i][step] for i in range(step))
            for candidate in prefix_map.get(prefix, []):
                curr.append(candidate)
                backtrack(step + 1)
                curr.pop()

        for w in words:
            curr.append(w)
            backtrack(1)
            curr.pop()

        return res

class Solution {
    int n;
    unordered_map<string, vector<string>> prefixMap;
    vector<vector<string>> res;
    vector<string> curr;

    void backtrack(int step) {
        if (step == n) {
            res.push_back(curr);
            return;
        }
        string prefix = "";
        for (int i = 0; i < step; i++) {
            prefix += curr[i][step];
        }
        auto it = prefixMap.find(prefix);
        if (it != prefixMap.end()) {
            for (const string& cand : it->second) {
                curr.push_back(cand);
                backtrack(step + 1);
                curr.pop_back();
            }
        }
    }
